		"colleagues.createDialog.rolePreset.frontend": "前端開發工程師",
		"colleagues.createDialog.rolePreset.frontendDesc": "負責前端介面設計與實現，擅長元件架構、互動細節、響應式適配和效能最佳化，保障體驗穩定。持續沉澱最佳實踐。",
		"colleagues.createDialog.rolePreset.seniorDeveloper": "高階開發工程師",
		"colleagues.createDialog.rolePreset.seniorDeveloperDesc": "負責複雜模組設計與技術攻堅，擅長架構權衡、效能最佳化、高併發處理和疑難問題定位，保障高質量交付。持續沉澱技術方案。",
		"colleagues.createDialog.rolePreset.wechatMiniProgram": "微信小程式開發員",
		"colleagues.createDialog.rolePreset.wechatMiniProgramDesc": "負責微信小程式開發框架和生態，體驗最佳化，保障流暢穩定。持續沉澱小程式實踐經驗，打造流暢微信原生體驗應用",
		"colleagues.createDialog.rolePreset.mobile": "移動端開發工程師",
		"colleagues.createDialog.rolePreset.mobileDesc": "負責 iOS、Android 與跨端應用開發，擅長互動實現、效能最佳化、相容適配和釋出質量保障。持續沉澱移動端實踐。",
		"colleagues.createDialog.rolePreset.aiEngineer": "AI工程師",
		"colleagues.createDialog.rolePreset.aiEngineerDesc": "負責大模型應用與智慧體開發，擅長 RAG、提示工程、流程編排和效果調優，推動 AI 能力落地業務。持續沉澱工程實踐。",
		"colleagues.createDialog.rolePreset.projectManager": "專案經理",
		"colleagues.createDialog.rolePreset.projectManagerDesc": "負責計劃排期、資源協調和風險管理，擅長跨團隊推進、進度跟蹤和按期交付保障。持續同步里程碑、風險和資源變化。",
		"colleagues.createDialog.rolePreset.ui": "UI設計師",
		"colleagues.createDialog.rolePreset.uiDesc": "負責介面視覺、元件規範和設計交付，擅長佈局、色彩、圖示和細節打磨，提升產品質感。持續沉澱規範，保障體驗一致。",
		"colleagues.createDialog.rolePreset.qa": "工程測試員",
		"colleagues.createDialog.rolePreset.qaDesc": "負責測試方案、用例設計和缺陷跟蹤，擅長自動化驗證、風險識別和上線質量保障。持續沉澱測試資產，提升交付信心。",
		"colleagues.createDialog.rolePreset.backendArchitect": "後端架構師",
		"colleagues.createDialog.rolePreset.backendArchitectDesc": "負責服務端架構與系統設計，擅長高併發、高可用、分層解耦和效能調優，保障系統穩定可擴充套件。持續沉澱架構方案。",
		"colleagues.createDialog.rolePreset.productAdmin": "產品管理員",
		"colleagues.createDialog.rolePreset.productAdminDesc": "負責計劃排期、資源協調和風險管理，擅長跨團隊推進、進度跟蹤和按期交付保障。持續同步里程碑、風險和資源變化。",
		"colleagues.createDialog.rolePreset.xiaohongshuOperator": "小紅書運營專員",
		"colleagues.createDialog.rolePreset.xiaohongshuOperatorDesc": "負責小紅書內容運營與增長，擅長選題策劃、爆款標題，深諳小紅書種草生態和推薦機制，打造高互動率種草內容，持續沉澱運營方法。",
		"colleagues.createDialog.rolePreset.contentCreator": "內容創作專員",
		"colleagues.createDialog.rolePreset.contentCreatorDesc": "負責內容策劃與創作產出，擅長選題挖掘、圖文指令碼、文案撰寫和質量把控，提升傳播效果。持續沉澱創作方法。",
		"colleagues.createDialog.rolePreset.stockResearcher": "股票研究員",
		"colleagues.createDialog.rolePreset.stockResearcherDesc": "負責個股研究與行情跟蹤，擅長財報解讀、估值分析、行業邏輯梳理和風險研判，輸出客觀研究結論。持續沉澱研究框架。",
		"colleagues.createDialog.rolePreset.industryResearcher": "行業研究員",
		"colleagues.createDialog.rolePreset.industryResearcherDesc": "負責行業研究與趨勢分析，擅長政策解讀、競爭格局梳理、資料驗證和洞察提煉，支撐業務決策。持續沉澱研究方法。",
		"colleagues.createDialog.rolePreset.dataAnalyst": "資料分析員",
		"colleagues.createDialog.rolePreset.dataAnalystDesc": "負責指標體系、資料看板和專題分析，擅長髮現業務問題、驗證假設並輸出清晰決策建議。持續沉澱分析方法，推動業務增長。",
		"colleagues.createDialog.rolePreset.experienceArchitect": "體驗架構師",
		"colleagues.createDialog.rolePreset.experienceArchitectDesc": "負責體驗策略、資訊架構和互動框架，擅長流程梳理、複雜場景拆解和一致性建設，化繁為簡提升體驗。持續沉澱體驗規範。",
		"colleagues.createDialog.rolePreset.webDeveloper": "Web開發工程師",
		"colleagues.createDialog.rolePreset.webDeveloperDesc": "負責 Web 應用前後端開發，擅長頁面實現、介面對接、效能最佳化和相容適配，保障交付效率與體驗。持續沉澱工程實踐。",
		"colleagues.createDialog.rolePreset.softwareArchitect": "軟體架構師",
		"colleagues.createDialog.rolePreset.softwareArchitectDesc": "負責系統架構與技術選型，擅長分層解耦、擴充套件性設計、穩定性建設和技術決策，保障系統可維護可生長。持續沉澱架構資產。",
		"colleagues.createDialog.rolePreset.codeReviewer": "程式碼審查員",
		"colleagues.createDialog.rolePreset.codeReviewerDesc": "負責程式碼評審與質量把關，擅長規範檢查、效能審視、隱患識別和改進建議，保障程式碼健康。持續沉澱評審規範，提升協作效率。",
		"colleagues.createDialog.rolePreset.gameDesigner": "遊戲設計師",
		"colleagues.createDialog.rolePreset.gameDesignerDesc": "負責玩法設計、數值平衡和關卡規劃，擅長核心迴圈搭建、體驗調優和系統打磨，提升可玩性與留存。持續沉澱設計方法。",
