		"collab.activity.detailDialog.title": "動態詳情",
		"collab.activity.fileChips.addToChat": "新增到任務",
		"collab.activity.fileChips.fileDeleted": "檔案已被刪除",
		"collab.activity.list.tooltipResourceLabel": "{verb}了 {typeLabel}：{names}",
		"collab.activity.mapper.fallbackUnnamedFile": "未命名檔案",
		"collab.activity.welcome.ariaLabel": "{productName} 歡迎留言",
		"collab.activity.welcome.body": "🎉 **歡迎來到 {productName} 專案——這裡是團隊和AI共同協作的工作臺**\n\n來帶你認識專案空間的核心功能：\n\n📁 **資產與專案配置**：團隊資源，全員共用\n專案文件、參考資料放進「資產」，團隊成員都能看到，我也會自動讀取參考。任務產出的檔案，也可以直接讓我存進資產裡——團隊隨時能查到最新產出。手頭好用的專家、Skill、聯結器，配置到專案裡，團隊成員發起任務都能使用。\n\n📋 **計劃看板**：分配、管理團隊工作\n想給團隊分工，直接跟我說 \"幫我把XX分給A，XX分給B\"，我會在「計劃」看板裡建好待辦，誰做什麼一目瞭然。之後有進展、有變化，我能在待辦中評論、@對應成員提醒——看板就是團隊的工作儀表盤。\n\n🤝 **任務協同**：實時協作，或者接力轉交\n有任務需要幾個人同時對著我討論、修改，在輸入框下方切換到「雲端任務」模式，之後在任務對話頁右上角發起「協作」，大家就能在同一個對話裡一起幹活。一件事你開了頭、想讓別人接手，可以把任務「轉交」給同事繼續推進，任務進度和當前成果會完整傳遞。\n\n⚙️ **定時任務**：讓重複工作自己跑起來\n有些流程需要定期處理——比如每天彙總新聞、定時拉取資料——可以在「定時任務」裡配好規則，到時間我會自動執行。執行時，我用的是跟你一樣的工具——該讀資產就讀資產，該建待辦就建待辦，團隊的工作流可以交給我自動處理。\n\n專案已經就位，祝順利開工 🙂",
