		"automation.templates.historyToday.title": "歷史上的今天",
		"automation.templates.historyToday.content": "從科技、電影、音樂等領域挑選一件\"今天發生過\"的有趣事件，200-300 字講清來龍去脈。",
		"automation.templates.dailyWhy.title": "每日一個為什麼",
