		"automation.templates.cutePetWallpaper.title": "可愛萌寵手機桌布",
		"automation.templates.cutePetWallpaper.content": "隨機從 7 種不同風格中挑選一種，為你生成一張 9:16 豎版高畫質萌寵手機桌布。",
		"automation.templates.parentContactReminder.title": "父母聯絡提醒",
		"automation.templates.parentContactReminder.content": "每週日 10:00 提醒你給家人打電話或發訊息，簡單問候近況。",
		"automation.templates.healthCheckupReminder.title": "體檢預約提醒",
		"automation.templates.healthCheckupReminder.content": "在 2026/04/08 07:00 提醒你確認體檢時間、準備證件，並注意空腹與其他事項。",
		"automation.templates.interviewPreparationReminder.title": "面試準備提醒",
		"automation.templates.interviewPreparationReminder.content": "工作日每 2 小時提醒你複習大模型面試內容，並生成 3 個模擬問題。",
		"automation.templates.preMeetingPreparation.title": "會議前準備",
		"automation.templates.preMeetingPreparation.content": "在會議開始前提醒你整理議題、目標、待確認問題和關鍵結論。",
		"automation.templates.dailyAiNews.prompt": "關注當天 AI 領域的重要動態，側重 AI coding 與具身智慧方向。篩選 3-5 條有價值的資訊，簡要說明事件內容及值得關注的原因。結合 memory.md 裡之前推送過的內容，儘量不要重複。",
		"automation.templates.dailyWords.prompt": "每天推薦 5 個實用英語單詞，優先選取生活和職場中常見詞彙。輸出詞義、音標、例句，以及一條便於記憶的小提示。結合 memory.md 裡之前推薦過的單詞，儘量不要重複。",
		"automation.templates.bedtimeStory.prompt": "寫一個適合兒童的睡前故事，語言溫和易懂，閱讀時長約 3-5 分鐘。故事需有完整情節，結尾附上簡短寓意。結合 memory.md 裡之前講過的故事，儘量不要重複。",
		"automation.templates.weeklyReport.prompt": "梳理本週倉庫中的 PR 與 Issue 情況，包括新增、已關閉及重點討論。輸出一份週報，涵蓋主要進展、關鍵變更和待關注事項。",
		"automation.templates.classicMovie.prompt": "給我推薦一部公認的經典電影（評分高、口碑好），簡要介紹劇情梗概、亮點所在，以及它為什麼值得一看，但是不要劇透。結合 memory.md 裡之前推薦過的電影，儘量不要重複。",
		"automation.templates.historyToday.prompt": "歷史上的今天發生過什麼有趣的事？從科技、電影、音樂等領域中挑一個，講講它的來龍去脈吧。控制在 200-300 字左右。",
		"automation.templates.dailyWhy.prompt": "隨機挑選一個有趣的冷知識或生活百科問題，並給出詳細、有趣、通俗易懂的解答。每次問題儘量不重複，覆蓋科學、生活、歷史、自然、食物、文化、動物、人體等多個領域；先丟擲問題再揭曉答案；語氣輕鬆有趣；答案控制在 200-300 字。",
		"automation.templates.parentContactReminder.prompt": "每週日十點提醒我給家人打電話或發訊息，簡單問候近況。",
		"automation.templates.healthCheckupReminder.prompt": "4月8號七點提醒我確認體檢時間、準備證件，提前空腹並留意注意事項。",
		"automation.templates.interviewPreparationReminder.prompt": "每兩小時提醒我複習關於大模型的專案亮點、技術難點、常見問答，並生成 3 個模擬面試問題。",
		"automation.templates.preMeetingPreparation.prompt": "在會議開始前，提醒我整理議題、目標、需要確認的問題，以及要同步的關鍵結論。",
		"automation.templates.cutePetWallpaper.prompt": "幫我生成一張手機桌布，以下主題隨機選一個就可以。\n主體：可愛萌寵。格式要求：手機桌布、高畫質解析度，size:576x1024，9:16 豎版比例。\n主題 1：毛絨絨雲朵主題，精美邊框，創意排版，漫畫浪漫主義，複雜華麗，漂浮雲朵元素，薄荷綠與天空藍主色調，溫柔可愛。\n主題 2：模糊感與筆觸感結合的極簡精緻插畫，深邃寶石藍背景，超現實主義美學，層次豐富，光影與反射形成視覺張力，同時保持和諧高階感。\n主題 3：武政諒風格卡通手機桌布，絲網印刷藝術風格，細膩顆粒肌理，柔和膠版印刷質感，極簡純扁平插畫，主體為貓咪，高飽和多巴胺色系。\n主題 4：虛擬電子風格，體素塊構成，亂碼與數字故障紋理，輕微失真星環，全息炫彩半透明水晶質感，隨機色彩斷層與掃描線，高飽和克萊因藍背景，蜜桃粉點綴。\n主題 5：精緻繪本插畫風格，線條簡潔流暢，高階米色單色調與大面積留白，略仰視角，淡雅水彩渲染，精緻可愛且有童趣。\n主題 6：復古主義風格，花卉佈局錯落有致，極繁細緻，以自然柔和色系為主，線條勾勒清晰，高飽和色彩呈現華麗質感。\n主題 7：隨手亂畫的極簡風，幼稚滑稽，潦草手繪，形象失真，稚拙可愛，同時帶一點夢境、故事感與治癒氛圍。\n請只選擇其中一個主題來創作，不要混用多個主題。\n結合 memory.md 裡之前生成過的主題，儘量選擇不同的主題，避免連續重複。",
