		"settings.securityCenter.ordered.fileTitle": "安全規則",
		"settings.securityCenter.ordered.fileDesc": "設定檔案路徑和讀取、寫入、刪除動作",
		"settings.securityCenter.ordered.fileInputTip": "支援\n• 可填寫檔案或資料夾路徑；使用者目錄可以用 ~ 表示。\n• * 比對目前層級中的任意名稱。\n範例\n• ~/.ssh/config：只比對這個檔案。\n• ~/Projects/*/dist/：比對每個專案的 dist 目錄及其全部內容。\n• /tmp/*.log：比對 /tmp 目錄下的 .log 檔案，不包含子目錄。\n注意\n• 目錄路徑請以 / 結尾，將比對該目錄及其全部內容。\n• 其他環境變數（如 $PWD）不會展開，請改用 ~ 或絕對路徑。",
		"settings.securityCenter.ordered.fileInputTipWindows": "支援\n• 可填寫磁碟機絕對路徑、UNC 網路路徑或使用者目錄路徑。\n• 使用者目錄支援 ~、%USERPROFILE%。\n• 也支援 %APPDATA%、%LOCALAPPDATA%、%TEMP%、%TMP%（依系統環境變數展開）。\n• * 比對目前層級中的任意名稱。\n範例\n• %USERPROFILE%\\.ssh\\config：只比對這個檔案。\n• %APPDATA%\\Code\\：比對 Roaming 應用程式資料目錄及其全部內容。\n• %TEMP%\\*.log：比對暫存目錄下的 .log 檔案。\n• D:\\logs\\*.log：比對該目錄下的 .log 檔案。\n注意\n• 目錄路徑請以 \\ 結尾，將比對該目錄及其全部內容。\n• $env:TEMP、%USERNAME% 等其他寫法不會依預期展開，請改用上面的形式或絕對路徑。",
		"settings.securityCenter.ordered.commandTitle": "命令規則",
		"settings.securityCenter.ordered.commandDesc": "設定命令前綴和命中後的處理動作",
		"settings.securityCenter.ordered.commandInputTip": "支援\n• 按「程式名稱 + 參數前綴」比對；程式名稱只看路徑最後一段，且不區分大小寫。\n• 參數按順序比對；規則前綴比對成功後，命令仍可繼續帶其他參數。\n• 獨立的 * 只比對一個參數；單獨填寫 * 比對所有命令。\n範例\n• git：比對 git 程式的所有呼叫，包括 /usr/bin/git；不比對 git-lfs。\n• git push：比對 git push、git push origin main；不比對 git pull。\n• docker * alpine：比對 docker run alpine、docker pull alpine；不比對 docker run --rm alpine。\n• *：比對所有命令。\n注意\n• 參數區分大小寫。\n• git*、--format=* 中的 * 視為一般字元。\n• 輸入按空白拆分，引號不能把含空格的文字合併為一個參數。",
		"settings.securityCenter.ordered.commandInputTipWindows": "支援\n• 按「程式名稱 + 參數前綴」比對；完整路徑只看最後的程式名稱，程式名稱不區分大小寫，.exe 可省略。\n• 參數按順序比對；規則前綴比對成功後，命令仍可繼續帶其他參數。\n• 獨立的 * 只比對一個參數；單獨填寫 * 比對所有命令。\n範例\n• python：比對 python、python.exe，以及完整路徑中的 python.exe。\n• git push：比對 git push、git push origin main；不比對 git pull。\n• docker * alpine：比對 docker run alpine、docker pull alpine；不比對 docker run --rm alpine。\n• *：比對所有命令。\n注意\n• 參數區分大小寫。\n• git*、--format=* 中的 * 視為一般字元。\n• 輸入按空白拆分，引號不能把含空格的文字合併為一個參數。",
		"settings.securityCenter.ordered.networkTitle": "網路規則",
		"settings.securityCenter.ordered.networkDesc": "設定網域和命中後的存取動作",
		"settings.securityCenter.ordered.networkInputTip": "支援\n• 可填寫精確網域、IPv4、以方括號包住的 IPv6 或 localhost。\n• *.example.com 比對 example.com 以及任意層級的子網域。\n• * 比對所有網路位址。\n• 網域不區分大小寫。\n範例\n• api.example.com：只比對該網域。\n• *.example.com：比對 example.com、api.example.com、a.b.example.com。\n• 127.0.0.1：比對該 IPv4 位址。\n• [::1]：比對該 IPv6 位址。\n• *：比對所有位址。\n輸入限制\n• 只填寫網域或 IP，不要包含通訊協定、連接埠、路徑、查詢參數或 CIDR。\n• 萬用字元僅支援 * 和 *.網域 兩種形式，例如 *.example.com。",
