		"settings.memory.modal.manage.loadFailed": "載入失敗",
		"settings.memory.modal.manage.mockMemory": "使用者偏好：\n- 喜歡簡潔的程式碼風格\n- 偏好使用 TypeScript\n- 習慣使用 React 函式元件\n- 工作時間通常在上午 9 點到下午 6 點\n\n技術棧：\n- 前端：React, TypeScript, Less\n- 後端：Node.js\n- 工具：VS Code, Git",
		"settings.memory.modal.import.title": "匯入其他記憶",
		"settings.memory.modal.import.step1": "複製以下提示詞到其他AI對話中",
		"settings.memory.modal.import.step1Desc": "",
		"settings.memory.modal.import.promptTemplate": "請幫我整理一份我的個人使用畫像，用途是讓我在不同 AI 工具之間保持一致的協作體驗。請基於你當前能訪問到的、與我相關的長期資訊和本次會話上下文進行整理。在涉及我的指令和偏好時，請儘量保留我原本的表述方式，不要過度改寫。\n\n分類（按以下順序輸出）\n指令：我明確要求遵循的規則，包括語氣、格式、風格、\"始終做 X\"、\"絕不做 Y\" 以及對助手行為的糾正。僅整理可從長期記憶中明確識別並客觀存在的規則，不臨時新增、不強加、不腦補未明確提出的要求。\n\n身份：姓名、年齡、所在地、教育背景、家庭、人際關係、語言能力和個人興趣（僅包含我主動分享過的非敏感資訊，不輸出證件號、聯絡方式、賬號等隱私資料）。\n\n職業：當前和過往的職位、公司以及主要技能領域。\n\n專案：我實際參與構建或投入精力的專案。每個專案一條。包含專案功能、當前狀態以及關鍵決策。以專案名稱或簡短描述作為條目開頭。\n\n偏好：廣泛適用的觀點、品味和工作風格偏好。\n\n格式\n使用分類標題作為每個類別的節標題。每個類別內，每行一條記錄，按日期從早到晚排列。每行格式：\n\n[YYYY-MM-DD] - 條目內容\n\n如果日期未知，使用 [unknown] 代替。\n\n輸出\n將整個畫像包裹在一個程式碼塊中，方便我複製。\n程式碼塊之後，簡要說明：這是否已覆蓋你當前能整理出的全部相關資訊；若還有未納入的維度或你不確定的條目，請列出來，由我判斷是否補充。",
